function MS(t,r){const u=MSC.ok[t];return u?`<img class="msc ${r?"r":""}" src="${u}" alt="${t}">`:""}
AV=function(t,name,team){const c=TC[t]||["#334155","#fff"];if(team){const u=MSC.ok[t];return u?`<span class="av m"><img src="${u}" alt="${t}"></span>`:`<span class="av tm" style="background:${c[0]};color:${c[1]}">${t}</span>`}
 const clean=name.replace(/\s*\(.*\)/,""),num=JN[t+"|"+clean];return`<span class="av" style="background:${c[0]};color:${c[1]}">${INI(clean)}${num!=null?`<i>#${num}</i>`:""}</span>`};
function AVI(t,name){const clean=name.replace(/\s*\(.*\)/,""),num=JN[t+"|"+clean],u=MSC.inj[t],c=TC[t]||["#334155","#fff"];if(!u)return AV(t,name);return`<span class="mb"><span class="mi"><img src="${u}" alt="${t} lesionado">${num!=null?`<i>#${num}</i>`:""}</span><b style="background:${c[0]};color:${c[1]}">${t}</b></span>`}
AV0=AV;AV=function(t,name,team){if(team&&MSC.ok[t]){const c=TC[t]||["#334155","#fff"];return`<span class="mb"><span class="mi"><img src="${MSC.ok[t]}" alt="${t}"></span><b style="background:${c[0]};color:${c[1]}">${t}</b></span>`}return AV0(t,name,team)};
try{draw()}catch(e){}
